"""Monthly per-account totals from a CSV of transactions. See task.md."""

from __future__ import annotations

import datetime
import os
import re


class RollupError(ValueError):
    """Raised for an input file that cannot be rolled up at all."""


_DATE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")
_AMOUNT = re.compile(r"(-?)([0-9]+)(?:\.([0-9]{1,4}))?")
_CURRENCY = re.compile(r"[A-Z]{3}")
_REQUIRED = ("id", "date", "account", "amount", "currency")


def _parse(text: str) -> list[list[str]]:
    """Split RFC 4180 text into records; completely empty lines are skipped."""
    records: list[list[str]] = []
    n = len(text)
    i = 0
    while i < n:
        if text[i] == "\n":
            i += 1
            continue
        if text.startswith("\r\n", i):
            i += 2
            continue
        fields: list[str] = []
        while True:
            buf: list[str] = []
            if i < n and text[i] == '"':
                i += 1
                while i < n:
                    c = text[i]
                    if c == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            buf.append('"')
                            i += 2
                        else:
                            i += 1
                            break
                    else:
                        buf.append(c)
                        i += 1
            while i < n and text[i] != "," and text[i] != "\n" and not text.startswith("\r\n", i):
                buf.append(text[i])
                i += 1
            fields.append("".join(buf))
            if i < n and text[i] == ",":
                i += 1
                continue
            if i < n and text[i] == "\n":
                i += 1
            elif i < n:
                i += 2
            break
        records.append(fields)
    return records


def _quote(field: str) -> str:
    if any(c in field for c in ',"\r\n'):
        return '"' + field.replace('"', '""') + '"'
    return field


def _line(fields) -> str:
    return ",".join(_quote(f) for f in fields) + "\n"


def _valid_date(value: str) -> bool:
    m = _DATE.fullmatch(value)
    if not m:
        return False
    try:
        datetime.date(int(m[1]), int(m[2]), int(m[3]))
    except ValueError:
        return False
    return True


def _units(value: str):
    """Amount in ten-thousandths as an int, or None if the syntax is invalid."""
    m = _AMOUNT.fullmatch(value)
    if not m:
        return None
    frac = (m[3] or "").ljust(4, "0")
    n = int(m[2]) * 10000 + int(frac)
    return -n if m[1] else n


def _format_total(units: int) -> str:
    cents = (abs(units) + 50) // 100
    sign = "-" if units < 0 and cents else ""
    return f"{sign}{cents // 100}.{cents % 100:02d}"


def build(input_csv: str, out_dir: str) -> None:
    """Read `input_csv`; write `<out_dir>/summary.csv` and `<out_dir>/rejects.csv`."""
    with open(input_csv, "rb") as fh:
        text = fh.read().decode("utf-8")
    if text.startswith("\ufeff"):
        text = text[1:]
    records = _parse(text)
    if not records:
        raise RollupError("no header record")
    header = records[0]
    if len(set(header)) != len(header):
        raise RollupError("duplicate column name in header")
    for name in _REQUIRED:
        if name not in header:
            raise RollupError(f"missing column {name!r}")
    idx = {name: header.index(name) for name in _REQUIRED}

    seen_ids: set[str] = set()
    currencies: dict[str, str] = {}
    groups: dict[tuple[str, str], list] = {}
    rejects: list[tuple[str, str, str]] = []

    for number, rec in enumerate(records[1:], 1):
        rec_id = rec[idx["id"]] if idx["id"] < len(rec) else ""
        reason = None
        units = None
        if len(rec) != len(header):
            reason = "malformed"
        else:
            id_, date, account, amount, currency = (rec[idx[k]] for k in _REQUIRED)
            units = _units(amount)
            if not id_ or not account or units is None or not _valid_date(date) or not _CURRENCY.fullmatch(currency):
                reason = "malformed"
            elif id_ in seen_ids:
                reason = "duplicate-id"
            elif currencies.get(account, currency) != currency:
                reason = "currency-mismatch"
        if reason:
            rejects.append((str(number), rec_id, reason))
            continue
        seen_ids.add(id_)
        currencies.setdefault(account, currency)
        g = groups.setdefault((account, date[:7]), [0, 0])
        g[0] += 1
        g[1] += units

    os.makedirs(out_dir, exist_ok=True)
    summary = [_line(("account", "month", "currency", "count", "total"))]
    for (account, month) in sorted(groups):
        count, total = groups[(account, month)]
        summary.append(_line((account, month, currencies[account], str(count), _format_total(total))))
    rej = [_line(("record", "id", "reason"))] + [_line(r) for r in rejects]
    for name, lines in (("summary.csv", summary), ("rejects.csv", rej)):
        with open(os.path.join(out_dir, name), "wb") as fh:
            fh.write("".join(lines).encode("utf-8"))
